import{_ as t,o as a,c as i,a4 as n}from"./chunks/framework.BUqnS5H7.js";const o=JSON.parse('{"title":"可观测性","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/06-engineering-practices/chapter-06-observability.md","filePath":"engineering/06-engineering-practices/chapter-06-observability.md"}'),r={name:"engineering/06-engineering-practices/chapter-06-observability.md"};function l(s,e,c,g,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="可观测性" tabindex="-1" data-src-line="1" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">可观测性 <a class="header-anchor" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="3" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><strong>核心问题</strong>：日志、指标、链路追踪三大支柱如何落地？如何快速定位线上问题？</p></blockquote><h2 id="_1-可观测性三大支柱" tabindex="-1" data-src-line="5" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">1. 可观测性三大支柱 <a class="header-anchor" href="#_1-可观测性三大支柱" aria-label="Permalink to &quot;1. 可观测性三大支柱&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="7" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">支柱</th><th style="text-align:left;">回答的问题</th><th style="text-align:left;">工具</th></tr></thead><tbody data-src-line="9" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="9" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">日志（Logging）</td><td style="text-align:left;">发生了什么？</td><td style="text-align:left;">ELK、Loki</td></tr><tr data-src-line="10" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">指标（Metrics）</td><td style="text-align:left;">系统状态如何？</td><td style="text-align:left;">Prometheus、Grafana</td></tr><tr data-src-line="11" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">链路追踪（Tracing）</td><td style="text-align:left;">请求经过了哪些服务？</td><td style="text-align:left;">SkyWalking、Jaeger</td></tr></tbody></table><p data-src-line="13" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">三者通过 TraceID 串联：日志提供细节，指标提供全局视图，链路追踪提供调用路径。</p><h2 id="_2-结构化日志" tabindex="-1" data-src-line="15" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">2. 结构化日志 <a class="header-anchor" href="#_2-结构化日志" aria-label="Permalink to &quot;2. 结构化日志&quot;">​</a></h2><p data-src-line="17" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">结构化日志的核心：用 JSON 等可解析格式输出，并携带请求上下文（如 userId、traceId），便于 ELK 检索。</p><blockquote data-src-line="19" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="19" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">各框架的结构化日志落地（MDC、Logback 配置）见 <a href="./../../spring/06-observability/chapter-01-logging.html">Spring 日志</a>。</p></blockquote><h2 id="_3-指标监控" tabindex="-1" data-src-line="21" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">3. 指标监控 <a class="header-anchor" href="#_3-指标监控" aria-label="Permalink to &quot;3. 指标监控&quot;">​</a></h2><p data-src-line="23" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">指标监控的核心：采集 QPS、响应时间、错误率、资源使用率等时间序列数据，配合告警规则及时发现异常。</p><blockquote data-src-line="25" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="25" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">Micrometer 与 Actuator 的指标暴露见 <a href="./../../spring/06-observability/chapter-02-metrics.html">Spring 指标</a>。</p></blockquote><h2 id="_4-链路追踪" tabindex="-1" data-src-line="27" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">4. 链路追踪 <a class="header-anchor" href="#_4-链路追踪" aria-label="Permalink to &quot;4. 链路追踪&quot;">​</a></h2><p data-src-line="29" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">链路追踪的核心：为每个请求生成 TraceID，贯穿所有下游调用，定位慢请求与错误传播路径。</p><blockquote data-src-line="31" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="31" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">SkyWalking / OpenTelemetry 的接入见 <a href="./../../spring/06-observability/chapter-03-tracing.html">Spring 链路追踪</a>。</p></blockquote><h2 id="_5-监控体系设计" tabindex="-1" data-src-line="33" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">5. 监控体系设计 <a class="header-anchor" href="#_5-监控体系设计" aria-label="Permalink to &quot;5. 监控体系设计&quot;">​</a></h2><table tabindex="0"><thead data-src-line="35" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="35" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">层次</th><th style="text-align:left;">监控内容</th><th style="text-align:left;">告警阈值</th></tr></thead><tbody data-src-line="37" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="37" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">基础设施</td><td style="text-align:left;">CPU、内存、磁盘、网络</td><td style="text-align:left;">CPU &gt; 80%、内存 &gt; 90%</td></tr><tr data-src-line="38" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">应用层</td><td style="text-align:left;">QPS、响应时间、错误率</td><td style="text-align:left;">错误率 &gt; 5%、P99 &gt; 1s</td></tr><tr data-src-line="39" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">业务层</td><td style="text-align:left;">订单量、支付成功率</td><td style="text-align:left;">支付成功率 &lt; 95%</td></tr></tbody></table><h2 id="_6-线上问题定位方法论" tabindex="-1" data-src-line="41" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">6. 线上问题定位方法论 <a class="header-anchor" href="#_6-线上问题定位方法论" aria-label="Permalink to &quot;6. 线上问题定位方法论&quot;">​</a></h2><h3 id="_6-1-三板斧-日志、指标、链路" tabindex="-1" data-src-line="43" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">6.1 三板斧：日志、指标、链路 <a class="header-anchor" href="#_6-1-三板斧-日志、指标、链路" aria-label="Permalink to &quot;6.1 三板斧：日志、指标、链路&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发现问题（告警/用户反馈）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>第一步：看指标（Grafana）—— 确定问题范围和影响</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>第二步：看链路（Jaeger/SkyWalking）—— 定位到具体环节</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>第三步：看日志（Kibana）—— 用 TraceID 找到异常堆栈</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>定位根因，制定修复方案</span></span></code></pre></div><h3 id="_6-2-常见问题排查路径" tabindex="-1" data-src-line="58" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">6.2 常见问题排查路径 <a class="header-anchor" href="#_6-2-常见问题排查路径" aria-label="Permalink to &quot;6.2 常见问题排查路径&quot;">​</a></h3><table tabindex="0"><thead data-src-line="60" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="60" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">问题现象</th><th style="text-align:left;">排查步骤</th><th style="text-align:left;">常见根因</th></tr></thead><tbody data-src-line="62" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="62" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">接口响应变慢</td><td style="text-align:left;">看 P99 趋势 → 找慢 Trace → 定位慢在哪个环节 → 看该环节日志</td><td style="text-align:left;">慢 SQL、缓存穿透、下游超时、GC 暂停</td></tr><tr data-src-line="63" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">偶发 500 错误</td><td style="text-align:left;">看错误率分布 → 搜 ERROR 日志 → 看异常堆栈 → 关联 TraceID</td><td style="text-align:left;">空指针、参数校验失败、并发竞争、连接池耗尽</td></tr><tr data-src-line="64" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">内存泄漏</td><td style="text-align:left;">看堆内存趋势 → 确认代区 → 生成堆转储 → 分析大对象</td><td style="text-align:left;">大集合未清理、ThreadLocal 泄露、缓存无上限</td></tr><tr data-src-line="65" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">CPU 飙高</td><td style="text-align:left;">找高 CPU 进程 → 找高 CPU 线程 → 转 16 进制 → 看线程堆栈</td><td style="text-align:left;">死循环、频繁 Full GC、正则回溯</td></tr><tr data-src-line="66" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">数据库连接池耗尽</td><td style="text-align:left;">看活跃连接数 → 确认是否达上限 → 查慢 SQL → 查事务关闭</td><td style="text-align:left;">慢 SQL 占连接、事务未提交、连接泄漏</td></tr></tbody></table><blockquote data-src-line="68" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="68" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">JVM 诊断工具（jmap、jstack、Arthas）的用法见 <a href="./../../spring/06-observability/chapter-04-production-debug.html">Spring 生产排查</a>。</p></blockquote><blockquote data-src-line="70" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="70" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><strong>核心原则</strong>：可观测性不是事后补充，而是从第一天就设计进去。</p></blockquote><h2 id="_7-本章小结" tabindex="-1" data-src-line="72" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">7. 本章小结 <a class="header-anchor" href="#_7-本章小结" aria-label="Permalink to &quot;7. 本章小结&quot;">​</a></h2><p data-src-line="74" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">可观测性三大支柱各司其职，又通过 TraceID 紧密关联：</p><table tabindex="0"><thead data-src-line="76" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="76" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">支柱</th><th style="text-align:left;">回答的问题</th><th style="text-align:left;">数据形态</th><th style="text-align:left;">代表技术栈</th></tr></thead><tbody data-src-line="78" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="78" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;"><strong>日志</strong></td><td style="text-align:left;">发生了什么？</td><td style="text-align:left;">离散事件</td><td style="text-align:left;">Logback → Filebeat → Elasticsearch → Kibana</td></tr><tr data-src-line="79" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;"><strong>指标</strong></td><td style="text-align:left;">整体状况如何？</td><td style="text-align:left;">时间序列数值</td><td style="text-align:left;">Micrometer → Prometheus → Grafana</td></tr><tr data-src-line="80" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;"><strong>链路追踪</strong></td><td style="text-align:left;">请求经过了哪里？哪里慢？</td><td style="text-align:left;">调用树</td><td style="text-align:left;">OpenTelemetry → Collector → Jaeger/SkyWalking</td></tr></tbody></table><p data-src-line="82" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">三者不是互斥选择，而是互补关系。日志提供细节，指标提供全局视图，链路追踪提供调用路径。通过 TraceID 将三者串联，才能构建完整的可观测体系。</p>`,27)])])}const h=t(r,[["render",l]]);export{o as __pageData,h as default};
